function paintViewer(){const it=viewerItems[viewerIndex];if(!it)return;vImg.src=it.src;vImg.alt=it.alt||'';vCount.textContent=`${String(viewerIndex+1).padStart(2,'0')} / ${String(viewerItems.length).padStart(2,'0')}`;vImg.style.transform='translateY(-50%) scale(1)';viewerScale=1;vPrev.hidden=viewerItems.length<2;vNext.hidden=viewerItems.length<2;}
function openViewer(items,index=0){viewerItems=items;viewerIndex=index;paintViewer();viewer.classList.add('open');document.body.style.overflow='hidden'}
function closeViewer(){viewer.classList.remove('open');vImg.style.transform='translateY(-50%) scale(1)';viewerScale=1;if(!$('#tn13Gallery').classList.contains('open')&&!masterPage.classList.contains('open'))document.body.style.overflow=''}
vPrev.onclick=()=>{viewerIndex=(viewerIndex-1+viewerItems.length)%viewerItems.length;paintViewer()};vNext.onclick=()=>{viewerIndex=(viewerIndex+1)%viewerItems.length;paintViewer()};viewer.querySelector('.tn22-view-close').onclick=closeViewer;viewer.addEventListener('click',e=>{if(e.target===viewer)closeViewer()});let sx=0,viewerScale=1,pinchStart=0;
const pinchDist=e=>Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);
vFrame.addEventListener('touchstart',e=>{if(e.touches.length===2){pinchStart=pinchDist(e)}else if(e.touches.length===1){sx=e.touches[0].clientX}},{passive:true});
vFrame.addEventListener('touchmove',e=>{if(e.touches.length===2&&pinchStart){e.preventDefault();viewerScale=Math.max(1,Math.min(3,pinchDist(e)/pinchStart));vImg.style.transform=`translateY(-50%) scale(${viewerScale})`}},{passive:false});
vFrame.addEventListener('touchend',e=>{if(e.changedTouches.length===1&&viewerScale===1&&viewerItems.length>1){const dx=e.changedTouches[0].clientX-sx;if(Math.abs(dx)>45)(dx<0?vNext:vPrev).click()}if(e.touches.length<2)pinchStart=0},{passive:true});

