const teamSheet=document.createElement('div');teamSheet.className='tn22-team-sheet';teamSheet.innerHTML=`<div class="tn22-team-panel"><div class="tn22-handle"></div><h3>Команда STLuxe</h3><div class="tn22-team-list">${MASTERS.map(m=>`<button class="tn22-team-row" type="button" data-sheet-mid="${m.id}"><span class="tn22-team-mini">${m.initial}</span><span><strong>${m.name}</strong><span>${m.role} · ${m.detail}</span></span><b>→</b></button>`).join('')}</div></div>`;root.appendChild(teamSheet);team.querySelector('.tn22-team-all').onclick=()=>{teamSheet.classList.add('open');document.body.style.overflow='hidden'};teamSheet.onclick=e=>{if(e.target===teamSheet){teamSheet.classList.remove('open');document.body.style.overflow=''}};

// MASTER PAGE
const masterPage=document.createElement('div');masterPage.className='tn22-master-page';masterPage.innerHTML=`<div class="tn22-master-shell"><div class="tn22-master-top"><button class="tn22-back" type="button">←</button><div class="tn22-master-brand">STLUXE</div><button class="tn22-master-menu" type="button">☰</button></div><div class="tn22-master-body"></div></div><button class="tn22-master-book" type="button">Записаться онлайн</button>`;root.appendChild(masterPage);masterPage.querySelector('.tn22-back').onclick=()=>{masterPage.classList.remove('open');document.body.style.overflow=''};masterPage.querySelector('.tn22-master-book').onclick=book;let currentMaster=null,currentMasterTab='Профиль';
function masterReviews(m){return REVIEW_DATA.filter(r=>m.reviewNames.includes(r[0]));}
function openMaster(id){currentMaster=MASTERS.find(m=>m.id===id);if(!currentMaster)return;const rs=masterReviews(currentMaster);const b=masterPage.querySelector('.tn22-master-body');const empty='<p class="tn23-master-empty">Информация пока не добавлена.</p>';b.innerHTML=`<div class="tn22-profile"><div class="tn22-profile-circle"><span>${currentMaster.initial}</span></div><h1>${currentMaster.name}</h1><div class="tn22-profile-role">${currentMaster.role} · ${currentMaster.detail}</div><div class="tn22-salon-rating"><b>★</b> 4,9 <span>рейтинг салона</span></div></div><div class="tn23-master-stack"><section class="tn23-master-section"><h3>О мастере</h3><p class="tn22-master-about" style="text-align:left;margin:0;max-width:none">${currentMaster.about||'Информация пока не добавлена.'}</p></section><section class="tn23-master-section"><h3>Услуги</h3>${empty}</section><section class="tn23-master-section"><h3>Портфолио</h3>${empty}</section><section class="tn23-master-section"><h3>Отзывы</h3>${rs.length?rs.map(r=>`<div class="tn23-master-review"><strong>${r[0]}</strong><p>${r[1]}</p></div>`).join(''):empty}</section></div>`;teamSheet.classList.remove('open');masterPage.classList.add('open');document.body.style.overflow='hidden'}
team.querySelectorAll('[data-mid]').forEach(b=>b.onclick=()=>openMaster(b.dataset.mid));teamSheet.querySelectorAll('[data-sheet-mid]').forEach(b=>b.onclick=()=>openMaster(b.dataset.sheetMid));

// REVIEWS
const reviews=$('#tn13Reviews');const rows=[REVIEW_DATA.slice(0,7),REVIEW_DATA.slice(7,14),REVIEW_DATA.slice(14,21)];
const card=r=>`<a class="tn22-review-card" href="${YANDEX_REVIEWS}" target="_blank" rel="noopener"><div class="tn22-review-head"><strong>${r[0]}</strong><span>★★★★★</span></div><p>${r[1]}</p></a>`;reviews.innerHTML=`<div class="tn22-reviews"><p class="tn22-kicker">Отзывы</p><h2>Что говорят о нас</h2><div class="tn22-score"><strong>4,9</strong><div><div class="tn22-stars">★★★★★</div><div class="tn22-count">86 отзывов на Яндекс Картах</div></div></div><div class="tn22-review-rows">${rows.map((r,i)=>`<div class="tn22-track${i===1?' reverse':''}" data-track>${r.map(card).join('')}${r.map(card).join('')}</div>`).join('')}</div><a class="tn22-review-all" href="${YANDEX_REVIEWS}" target="_blank" rel="noopener">Смотреть все отзывы на Яндекс Картах →</a></div>`;reviews.querySelectorAll('[data-track]').forEach((t,i)=>{let offset=0,half=0,drag=false,startX=0,startOffset=0,moved=false,resumeAt=0,last=performance.now();const dir=i===1?-1:1,speed=12;const measure=()=>{half=t.scrollWidth/2;if(i!==1&&offset===0)offset=-half};requestAnimationFrame(measure);window.addEventListener('resize',measure,{passive:true});const wrap=()=>{if(!half)return;if(offset>=0)offset=-half;if(offset<=-half)offset=0};t.addEventListener('pointerdown',e=>{drag=true;moved=false;resumeAt=Infinity;startX=e.clientX;startOffset=offset;t.classList.add('dragging');try{t.setPointerCapture(e.pointerId)}catch(_){}});t.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-startX;if(Math.abs(dx)>3)moved=true;offset=startOffset+dx;wrap();t.style.transform=`translate3d(${offset}px,0,0)`});const release=()=>{if(!drag)return;drag=false;t.classList.remove('dragging');resumeAt=performance.now()+800};t.addEventListener('pointerup',release);t.addEventListener('pointercancel',release);t.addEventListener('click',e=>{if(moved){e.preventDefault();e.stopPropagation()}},true);const tick=now=>{const dt=Math.min(50,now-last);last=now;if(!drag&&now>=resumeAt){offset+=dir*speed*dt/1000;wrap();t.style.transform=`translate3d(${offset}px,0,0)`}requestAnimationFrame(tick)};requestAnimationFrame(tick)});

// VISIT
const visit=$('#tn13Visit');const pin=`<svg viewBox="0 0 24 24"><path d="M12 21s6-5.3 6-11a6 6 0 1 0-12 0c0 5.7 6 11 6 11Z"/><circle cx="12" cy="10" r="2.2"/></svg>`,ph=`<svg viewBox="0 0 24 24"><path d="M7.3 3.5 10 7.3 8.2 9.1c1.5 3 3.8 5.3 6.8 6.8l1.8-1.8 3.8 2.7c.2.2.3.5.2.8-.5 1.8-2 3-3.9 3C10 20.6 3.4 14 3.4 7.1c0-1.9 1.2-3.4 3-3.9.3-.1.7 0 .9.3Z"/></svg>`,clock=`<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3.2 1.8"/></svg>`;
visit.innerHTML=`<div class="tn22-visit"><div class="tn22-visit-head"><p class="tn22-kicker">Контакты</p><span class="tn22-status" id="tn22Status"><span class="tn22-status-text"></span>${clock}</span></div><h2>Ждём вас</h2><div class="tn22-contact-grid"><a class="tn22-contact" href="${YANDEX_RU}" target="_blank" rel="noopener">${pin}<span><strong>Ивантеевка, ул. Победы, 16</strong><span>Московская область · открыть в Яндекс Картах</span></span></a><a class="tn22-contact" href="tel:${PHONE}">${ph}<span><strong>+7 (916) 355-22-22</strong><span>Нажмите, чтобы позвонить</span></span></a><div class="tn22-contact">${clock}<span><strong>Вт–Вс 10:00–20:00</strong><span>Понедельник — выходной</span></span></div></div><div class="tn22-mapwrap"><div class="tn22-map-skeleton">Загружаем карту…</div><iframe title="Карта STLuxe" loading="eager" src="https://yandex.ru/map-widget/v1/?mode=search&text=%D0%98%D0%B2%D0%B0%D0%BD%D1%82%D0%B5%D0%B5%D0%B2%D0%BA%D0%B0%2C%20%D1%83%D0%BB.%20%D0%9F%D0%BE%D0%B1%D0%B5%D0%B4%D1%8B%2C%2016&z=16"></iframe></div><div class="tn22-visit-actions"><a class="tn22-visit-btn tn22-call" href="tel:${PHONE}">Позвонить</a><a class="tn22-visit-btn tn22-route" href="${ROUTE}" target="_blank" rel="noopener">Построить маршрут</a></div><a class="tn22-footer" href="https://tanem.ru/" target="_blank" rel="noopener"><strong>TANEM.ru</strong><span>Цифровой офис для салонов красоты</span></a></div>`;
const map=visit.querySelector('.tn22-mapwrap'),iframe=map.querySelector('iframe');iframe.addEventListener('load',()=>map.classList.add('loaded'));setTimeout(()=>map.classList.add('loaded'),5000);
function status(){const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Moscow',weekday:'short',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(new Date());const get=t=>parts.find(x=>x.type===t)?.value||'';const day=get('weekday'),h=+get('hour'),m=+get('minute'),mins=h*60+m;const el=visit.querySelector('#tn22Status');const monday=day==='Mon',open=!monday&&mins>=600&&mins<1200;const txt=el.querySelector('.tn22-status-text');if(open){txt.textContent='Открыто до 20:00';el.className='tn22-status open'}else{txt.textContent=monday?'Закрыто до вт 10:00':'Закрыто до 10:00';el.className='tn22-status closed'}}status();setInterval(status,60000);

